  /// as a string instead of an HTTP request.
  factory AiinCallback.fromRedirectUrl(String url) {
    final query =
        Uri.tryParse(url)?.queryParameters ?? const <String, String>{};
    return AiinCallback(
      code: query['code'],
      state: query['state'],
      error: query['error'],
      errorDescription: query['error_description'],
